        int diaria;
        if (n <= 15) {
            diaria = d + (n - 1) * a;
        } else {
            diaria = d + 14 * a;
        }

        int dias = 31 - n + 1;
        long total = (long) diaria * dias;

        System.out.println(total);
    }
}
